-				words = append(words, clean[0])
+				commands = append(commands, toolCommand{clean[0], key, run})
+			}
+			return nil
+		}
+		for i, run := range cfg.Setup {
+			if err := add(fmt.Sprintf("commands.setup[%d]", i), run); err != nil {
+				return err
+			}
+		}
+		for i, run := range cfg.Fix {
+			if err := add(fmt.Sprintf("commands.fix[%d]", i), run); err != nil {
+				return err
+			}
+		}
+		for _, ch := range cfg.Checks {
+			if err := add("commands.checks["+ch.Name+"]", ch.Run); err != nil {
+				return err
+			}
+		}
+		if cfg.Acceptance != nil && cfg.Acceptance.Run != "" {
+			if err := add("commands.acceptance.run", cfg.Acceptance.Run); err != nil {
+				return err
 			}
 		}
 	}
+	words := []string{"git"}
+	for _, c := range commands {
+		words = append(words, c.word)
+	}
 	seen := map[string]bool{}
-	for _, word := range slices.Concat([]string{"git"}, words) {
+	for _, word := range words {
 		if seen[word] {
 			continue
 		}
@@ -624,7 +650,22 @@ func RequireTools(s *sys.Session, tools Tools, root string, cfg *project.Config,
 		cmd.Dir = root
 		cmd.Env = append(slices.Clone(s.Env), "PATH="+s.Getenv("PATH"))
 		if err := cmd.Run(); err != nil {
-			return sys.Fail("environment", "tool_missing", word+" is not available", 3)
+			e := sys.Fail("environment", "tool_missing", word+" is not available", 3)
+			if word == "git" {
+				e.Lines = []string{"next: install git, then rerun the command that was refused"}
+				return e
+			}
+			for _, c := range commands {
+				if c.word == word {
+					e.Lines = append(e.Lines, c.key+": "+(*Redactor)(nil).Redact(c.run))
+				}
+			}
+			if word == "$KOGEN_NODE" {
+				e.Lines = append(e.Lines, "next: reinstall Kogen, then rerun the command that was refused")
+			} else {
+				e.Lines = append(e.Lines, "next: install "+word+" or change that command in .kogen/project.yaml (commit the change), then rerun the command that was refused")
+			}
+			return e
 		}
 	}
 	return nil

